const r = $input.first().json;

// Sanitize: strip control chars, limit length
const clean = (s, maxLen) => {
  if (!s) return '';
  return String(s).replace(/[\x00-\x1F\x7F]/g, ' ').trim().substring(0, maxLen);
};

// Whitelist enums
const VALID_INTENTS = ['informationnelle', 'comparative', 'décisionnelle', 'transactionnelle', 'navigationnelle'];
const VALID_PILIERS = ['SEO', 'LMS', 'CRM', 'Performance', 'Automatisation', 'Ecommerce', 'Formation', 'Freelance'];
const VALID_OBJECTIFS = ['email', 'affiliation', 'formation', 'offre'];

const rawIntent = (r['Intent'] || r.intent || '').trim();
const rawPilier = (r['Pilier'] || r.pilier || '').trim();
const rawObjectif = (r['Objectif'] || r.objectif || '').trim();

const intent = VALID_INTENTS.includes(rawIntent) ? rawIntent : 'informationnelle';
const pilier = VALID_PILIERS.includes(rawPilier) ? rawPilier : 'SEO';
const objectif = VALID_OBJECTIFS.includes(rawObjectif) ? rawObjectif : 'formation';

const sujet = clean(r['Sujet'] || r.sujet, 200);
const keyword = clean(r['Mot-clé principal'] || r.keyword, 120);
const audience = clean(r['Public'] || r.audience, 200);

if (!sujet && !keyword) {
  throw new Error('Ligne IDEAS invalide : Sujet et Mot-clé manquants — ligne ignorée');
}

return [{ json: {
  row_number: r.row_number || 1,
  sujet: sujet || keyword,
  keyword: keyword || sujet,
  intent,
  pilier,
  audience: audience || 'freelance WordPress',
  objectif
} }];

const c = $input.first().json;
const sys = `Tu es schoolsWP Brain, stratège WordPress.
Retourne UNIQUEMENT un JSON valide (sans backticks) :
{"angle":"string","opportunite":"affilié|formation|lead magnet|agence","audience":"string","competition":"faible|moyen|élevé","points_cles":["p1","p2","p3"]}
schoolsWP (schoolswp.com) : freelances, formateurs, solopreneurs WordPress.`;
const msg = `Sujet : ${c.sujet}
Mot-clé : ${c.keyword}
Intent : ${c.intent}
Pilier : ${c.pilier}
Audience : ${c.audience}`;
return [{ json: { ...c, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 800, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Map Inputs').first().json;
let brain = { angle: '', opportunite: 'formation', audience: prev.audience, competition: 'moyen', points_cles: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  brain = { ...brain, ...JSON.parse(raw) };
} catch(e) {}
const pts = (brain.points_cles || []).join(', ');
const sys = `Tu es le Rédacteur SEO de schoolsWP (schoolswp.com).
Rédige un article SEO complet en markdown — 1500-2500 mots.
Structure : H1 optimisé (mot-clé dans le titre) → introduction (problème → solution, accroche directe) → corps H2/H3 logiques → tableau comparatif si pertinent → conclusion (3 points retenus + 1 action concrète).
Tutoiement systématique. Ton direct, pédagogique, chaleureux.
Mots interdits : disruptif, game changer, scalable, révolutionnaire, hack, incroyable, "en un clic", "sans effort", "il suffit de".
Chiffres réels ou estimations sourcées uniquement. CTA naturels et utiles (jamais agressifs).
Commence directement par le H1. Zéro préambule, zéro commentaire.`;
const msg = `Mot-clé cible : ${prev.keyword}
Sujet : ${prev.sujet}
Intent : ${prev.intent}
Angle différenciant : ${brain.angle || 'à définir'}
Audience : ${brain.audience}
Points obligatoires à couvrir : ${pts || 'non précisés'}`;
return [{ json: { ...prev, angle: brain.angle, audience_refined: brain.audience, opportunite: brain.opportunite, competition: brain.competition, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 8000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse Brain').first().json;
const v1 = $input.first().json.content[0].text;
const sys = `Tu es l'Optimiseur LLM-SEO de schoolsWP.
Injecte dans l'article les 3 blocs suivants, à l'endroit le plus logique (après le H1 ou avant la conclusion) :

### Réponse rapide
[≤60 mots, autonome, extractible par AI Overview]

### Points clés
– [point factuel 1]
– [point factuel 2]
– [point factuel 3]

### En résumé
[≤80 mots, synthèse de l'article]

Conserve intégralement le contenu existant. Commence directement par le H1. Aucun commentaire.`;
const msg = `Mot-clé : ${prev.keyword}

${v1}`;
return [{ json: { ...prev, v1, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 10000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse V1').first().json;
const v_llm = $input.first().json.content[0].text;
const sys = `Tu es l'Auditeur SEO de schoolsWP.
Analyse l'article et retourne UNIQUEMENT un JSON valide (sans backticks, sans commentaires) :
{"score_seo":85,"structure":20,"intention":22,"champ_lexical":23,"lisibilite":20,"faiblesses":["...","..."],"actions":["action 1","action 2","action 3"]}
Chaque sous-score sur 25. score_seo = somme des 4 (max 100).
Évalue : structure H1/H2/H3, alignement intention SEO, champ lexical, lisibilité.`;
const msg = `Mot-clé : ${prev.keyword}
Intent : ${prev.intent}

${v_llm}`;
return [{ json: { ...prev, v_llm, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse LLM').first().json;
let audit_seo = { score_seo: 70, structure: 17, intention: 17, champ_lexical: 18, lisibilite: 18, faiblesses: [], actions: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  audit_seo = { ...audit_seo, ...JSON.parse(raw) };
} catch(e) {}
const sys = `Tu es l'Auditeur Conversion de schoolsWP.
Analyse l'article et retourne UNIQUEMENT un JSON valide (sans backticks, sans commentaires) :
{"score_conversion":75,"clarte_probleme":15,"decision":18,"orientation_action":16,"cta":10,"business_alignment":16,"faiblesses":["...","..."],"actions":["action 1","action 2"]}
Chaque sous-score sur 20. score_conversion = somme des 5 (max 100).
Évalue : clarté du problème, logique décisionnelle, orientation vers l'action, qualité CTA, cohérence business schoolsWP.`;
const msg = `Mot-clé : ${prev.keyword}
Intent : ${prev.intent}
Objectif business : ${prev.objectif}

${prev.v_llm}`;
return [{ json: { ...prev, audit_seo, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse SEO Audit').first().json;
let audit_conv = { score_conversion: 70, clarte_probleme: 14, decision: 14, orientation_action: 14, cta: 14, business_alignment: 14, faiblesses: [], actions: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  audit_conv = { ...audit_conv, ...JSON.parse(raw) };
} catch(e) {}
const sys = `Tu es l'Auditeur Topical Authority de schoolsWP.
Analyse l'article et retourne UNIQUEMENT un JSON valide (sans backticks, sans commentaires) :
{"score_autorite":80,"couverture":18,"connexions":15,"coherence":16,"positionnement":16,"potentiel_cluster":15,"manques":["...","..."],"actions":["action 1","action 2"]}
Chaque sous-score sur 20. score_autorite = somme des 5 (max 100).
Évalue : couverture thématique, connexions avec l'écosystème WordPress, cohérence éditoriale, positionnement schoolsWP, potentiel de cluster sémantique.`;
const msg = `Mot-clé : ${prev.keyword}
Pilier schoolsWP : ${prev.pilier}

${prev.v_llm}`;
return [{ json: { ...prev, audit_conv, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse Conversion Audit').first().json;
let audit_auth = { score_autorite: 70, couverture: 14, connexions: 14, coherence: 14, positionnement: 14, potentiel_cluster: 14, manques: [], actions: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  audit_auth = { ...audit_auth, ...JSON.parse(raw) };
} catch(e) {}
const seo = prev.audit_seo.score_seo || 70;
const conv = prev.audit_conv.score_conversion || 70;
const auth = audit_auth.score_autorite || 70;
const publish_score = Math.round(seo * 0.35 + conv * 0.30 + auth * 0.35);
const emoji = publish_score >= 85 ? '✅' : (publish_score >= 75 ? '🟡' : '🔴');
const diag = publish_score >= 85 ? 'Publication immédiate' : (publish_score >= 75 ? '1–2 optimisations ciblées' : 'Révision substantielle');
const weakest = seo <= conv && seo <= auth ? 'SEO' : (conv <= auth ? 'Conversion' : 'Autorité');
const all_actions = [
  ...(prev.audit_seo.actions || []).slice(0, 2),
  ...(prev.audit_conv.actions || []).slice(0, 2),
  ...(audit_auth.actions || []).slice(0, 2)
];
const faiblesses = [
  ...(prev.audit_seo.faiblesses || []).slice(0, 2),
  ...(prev.audit_conv.faiblesses || []).slice(0, 2)
].join(' | ');
const sys = `Tu es l'Éditeur Senior de schoolsWP.
Si le Publish Score indiqué est >= 85 : retourne l'article EXACTEMENT tel quel, sans aucune modification ni commentaire.
Si Publish Score < 85 : améliore uniquement les sections faibles selon le diagnostic. Conserve la structure globale, le tutoiement, le ton. Commence directement par le H1.`;
const msg = `Publish Score : ${publish_score}/100 (${diag})
Bloc le plus faible : ${weakest}
Actions prioritaires : ${all_actions.join(' | ')}
Faiblesses : ${faiblesses}

--- ARTICLE ---

${prev.v_llm}`;
return [{ json: { ...prev, audit_auth, publish_score, emoji, diag, weakest, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 8000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Compute Publish Score').first().json;
const article_final = $input.first().json.content[0].text;
const sys = `Tu es le Stratège Cluster de schoolsWP.
Retourne UNIQUEMENT un JSON valide (sans backticks, sans commentaires) :
{"role":"Pilier|Satellite|À renforcer","satellites":[{"titre":"string","intention":"informationnelle|comparative|décisionnelle","lien_logique":"string","priorite":1},{"titre":"...","intention":"...","lien_logique":"...","priorite":2},{"titre":"...","intention":"...","lien_logique":"...","priorite":3}],"maillage":["ancre naturelle → /url-relative","ancre 2 → /url-2"]}
Piliers schoolsWP : SEO WordPress / LMS WordPress / CRM WordPress / Performance / Automatisation.`;
const msg = `Mot-clé : ${prev.keyword}
Pilier : ${prev.pilier}
Intent : ${prev.intent}

${article_final}`;
return [{ json: { ...prev, article_final, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1200, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse V2').first().json;
let cluster = { role: 'Satellite', satellites: [], maillage: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  cluster = { ...cluster, ...JSON.parse(raw) };
} catch(e) {}
const sys = `Tu es le Copywriter CTA de schoolsWP.
Génère 1 bloc CTA soft en markdown, tutoiement, max 80 mots.
Adapte l'objectif business spécifié. Propose une ressource concrète (guide, checklist, formation).
Style : utile, direct, jamais agressif. Disclosure affilié si pertinent : "(lien affilié — soutient schoolsWP sans surcoût)".
Retourne uniquement le bloc markdown. Aucun commentaire préliminaire.`;
const msg = `Mot-clé : ${prev.keyword}
Objectif business : ${prev.objectif}
Opportunité : ${prev.opportunite}
Pilier : ${prev.pilier}`;
return [{ json: { ...prev, cluster, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 500, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse Cluster').first().json;
const cta_block = $input.first().json.content[0].text;
const sys = `Tu es l'Expert SEO Meta de schoolsWP.
Retourne UNIQUEMENT un JSON valide (sans backticks, sans commentaires) :
{"title":"Titre SEO ≤60 chars","description":"Meta description ≤155 chars, incite au clic","json_ld":{"@context":"https://schema.org","@type":"Article","headline":"string","description":"string","publisher":{"@type":"Organization","name":"schoolsWP","url":"https://schoolswp.com"}}}
Le title doit contenir le mot-clé principal. La description doit inclure un bénéfice clair et inciter au clic.`;
const msg = `Mot-clé : ${prev.keyword}
Sujet : ${prev.sujet}
Intent : ${prev.intent}`;
return [{ json: { ...prev, cta_block, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 600, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Assemble Final').first().json;
const docId = $input.first().json.documentId || '';
const batchUpdateBody = {
  requests: [{
    insertText: {
      location: { index: 1 },
      text: prev.final_content
    }
  }]
};
return [{ json: { ...prev, documentId: docId, batchUpdateBody } }];

const prev = $('Code - Prepare Doc Update').first().json;
const docUrl = prev.documentId ? `https://docs.google.com/document/d/${prev.documentId}/edit` : 'N/D';
return [{ json: {
  'Sujet': prev.sujet,
  'Mot-clé principal': prev.keyword,
  'Statut': 'Généré ✓',
  'Priorité': prev.priority,
  'Publish Score': String(prev.publish_score),
  'Lien Google Doc': docUrl
} }];
